$(function () {
  $("a.scrollTo").click(function () {
    (window.opera
      ? "CSS1Compat" == document.compatMode
        ? $("html")
        : $("body")
      : $("html,body")
    ).animate({ scrollTop: 0 }, 600);
    return !1;
  });
  $("a.scrollBtm").click(function () {
    $("html, body").animate({ scrollTop: $(document).height() }, "slow");
    return !1;
  });
});
$(window).scroll(function () {
  300 < $(window).scrollTop()
    ? $("a.scrollTo").css("opacity", "1").show()
    : 0 == $(window).scrollTop()
      ? $("a.scrollTo").css("opacity", "0")
      : ($(window).scrollTop(), $("a.scrollTo").css("opacity", "1"));
  300 > $(window).scrollTop()
    ? $("a.scrollBtm").css("opacity", "1").show()
    : 0 == $(window).scrollTop()
      ? $("a.scrollBtm").css("opacity", "1")
      : $("a.scrollBtm").css("opacity", "0");
  $(window).scrollTop() + $(window).height() == $(document).height() &&
    $("a.scrollBtm").css("opacity", "0");
});
